import { useEffect, useState } from "react";
import api from "../utils/api";
import LogoutButton from "../components/LogoutButton"; // ⬅️ import here

export default function AdminDashboard() {
  const [pendingUsers, setPendingUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [newCandidate, setNewCandidate] = useState({ name: "", position: "", party: "" });

  // Fetch pending users and candidates
  useEffect(() => {
    fetchPendingUsers();
    fetchCandidates();
  }, []);

  const fetchPendingUsers = async () => {
    try {
      const res = await api.get("/admin/pending-users");
      setPendingUsers(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  const fetchCandidates = async () => {
    try {
      const res = await api.get("/admin/candidates");
      setCandidates(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  const approveUser = async (id) => {
    try {
      await api.patch(`/admin/approve-user/${id}`);
      setPendingUsers((prev) => prev.filter((u) => u.id !== id));
    } catch (err) {
      console.error(err);
    }
  };

  const deleteUser = async (id) => {
    try {
      await api.delete(`/admin/user/${id}`);
      setPendingUsers((prev) => prev.filter((u) => u.id !== id));
    } catch (err) {
      console.error(err);
    }
  };

  const addCandidate = async (e) => {
    e.preventDefault();
    try {
      const res = await api.post("/admin/candidates", newCandidate);
      setCandidates((prev) => [...prev, res.data]);
      setNewCandidate({ name: "", position: "", party: "" });
    } catch (err) {
      console.error(err);
    }
  };

  const deleteCandidate = async (id) => {
    try {
      await api.delete(`/admin/candidates/${id}`);
      setCandidates((prev) => prev.filter((c) => c.id !== id));
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div className="p-6">
      {/* Header with Logout */}
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold">Admin Dashboard</h1>
        <LogoutButton /> {/* ⬅️ here */}
      </div>

      {/* Pending Users */}
      <section className="mb-10">
        <h2 className="text-xl font-semibold mb-4">Pending Users</h2>
        {pendingUsers.length === 0 ? (
          <p>No pending users.</p>
        ) : (
          <ul className="space-y-2">
            {pendingUsers.map((user) => (
              <li key={user.id} className="p-3 border rounded flex justify-between items-center">
                <span>
                  {user.name} ({user.email})
                </span>
                <div className="space-x-2">
                  <button
                    onClick={() => approveUser(user.id)}
                    className="bg-green-500 text-white px-3 py-1 rounded"
                  >
                    Approve
                  </button>
                  <button
                    onClick={() => deleteUser(user.id)}
                    className="bg-red-500 text-white px-3 py-1 rounded"
                  >
                    Delete
                  </button>
                </div>
              </li>
            ))}
          </ul>
        )}
      </section>

      {/* Candidates */}
      <section>
        <h2 className="text-xl font-semibold mb-4">Candidates</h2>

        <form onSubmit={addCandidate} className="flex gap-2 mb-4">
          <input
            type="text"
            placeholder="Name"
            value={newCandidate.name}
            onChange={(e) => setNewCandidate({ ...newCandidate, name: e.target.value })}
            className="border p-2 rounded"
            required
          />
          <input
            type="text"
            placeholder="Position"
            value={newCandidate.position}
            onChange={(e) => setNewCandidate({ ...newCandidate, position: e.target.value })}
            className="border p-2 rounded"
            required
          />
          <input
            type="text"
            placeholder="Party (optional)"
            value={newCandidate.party}
            onChange={(e) => setNewCandidate({ ...newCandidate, party: e.target.value })}
            className="border p-2 rounded"
          />
          <button type="submit" className="bg-blue-500 text-white px-4 py-2 rounded">
            Add
          </button>
        </form>

        {candidates.length === 0 ? (
          <p>No candidates yet.</p>
        ) : (
          <ul className="space-y-2">
            {candidates.map((c) => (
              <li key={c.id} className="p-3 border rounded flex justify-between items-center">
                <span>
                  {c.name} - {c.position} {c.party && `(${c.party})`}
                </span>
                <button
                  onClick={() => deleteCandidate(c.id)}
                  className="bg-red-500 text-white px-3 py-1 rounded"
                >
                  Delete
                </button>
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  );
}
